document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".case-study-tabs-section").forEach(e=>{const t=e.querySelectorAll(".case-study-tabs-section__tab"),s=e.querySelectorAll(".case-study-tabs-section__image");t.length&&s.length&&t.forEach(e=>{e.addEventListener("click",()=>{if(e.classList.contains("is-active"))return;const a=e.dataset.index;t.forEach(e=>{e.classList.remove("is-active"),e.setAttribute("aria-selected","false")}),e.classList.add("is-active"),e.setAttribute("aria-selected","true"),s.forEach(e=>{e.classList.toggle("is-active",e.dataset.index===a)})})})})});